import json
from pathlib import Path
import pandas as pd

source = Path('/Users/adarsh/Downloads/Sample data (1).xlsx')
out = Path('/Users/adarsh/Documents/Codex/2026-10-29/create-a-dashboard-in-power-bi/outputs')
out.mkdir(parents=True, exist_ok=True)
df = pd.read_excel(source)
df.columns = [str(c).strip() for c in df.columns]
df['Date'] = pd.to_datetime(df['Date']).dt.strftime('%Y-%m-%d')
df['Discount Band'] = df['Discount Band'].fillna('Not specified')
rows = df.to_dict(orient='records')
for row in rows:
    for k, v in row.items():
        if pd.isna(v): row[k] = None
        elif hasattr(v, 'item'): row[k] = v.item()
data = json.dumps(rows, separators=(',', ':'), ensure_ascii=False)
html = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Performance Dashboard</title>
<style>
:root{--bg:#f4f6f8;--card:#fff;--ink:#132238;--muted:#65748a;--line:#e8edf2;--blue:#2367f2;--teal:#10a7a0;--orange:#f3a33b;--red:#e76f51;--shadow:0 8px 24px #162f4d0a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{max-width:1440px;margin:auto;padding:30px 34px 42px}.top{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px}.eyebrow{text-transform:uppercase;letter-spacing:.14em;color:var(--blue);font-size:10px;font-weight:800}.top h1{font-size:28px;letter-spacing:-.04em;margin:5px 0}.sub{color:var(--muted)}.tag{background:#e9f1ff;color:#2367f2;border-radius:20px;padding:8px 12px;font-weight:700;font-size:11px}.filters{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0 18px}.filter{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:8px 11px;display:flex;gap:8px;align-items:center;box-shadow:var(--shadow)}.filter label{color:var(--muted);font-size:11px}.filter select{border:0;background:transparent;color:var(--ink);font-size:12px;font-weight:700;outline:none;min-width:108px}.reset{border:0;background:var(--ink);color:#fff;border-radius:10px;padding:0 15px;font-weight:700;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:15px}.card{background:var(--card);border:1px solid #edf0f4;border-radius:15px;padding:18px 19px;box-shadow:var(--shadow);min-width:0}.kpi{grid-column:span 3;min-height:119px}.kpi-label{color:var(--muted);font-size:12px;font-weight:600}.kpi-value{font-size:26px;letter-spacing:-.04em;font-weight:800;margin:7px 0 2px}.kpi-note{font-size:11px;color:var(--muted)}.kpi-note strong{color:var(--teal)}.chart{grid-column:span 6;min-height:310px}.wide{grid-column:span 8}.narrow{grid-column:span 4}.chart-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px}.chart h2{font-size:14px;margin:0 0 3px}.chart p{font-size:11px;color:var(--muted);margin:0}.legend{font-size:10px;color:var(--muted)}.chart-area{height:225px;position:relative}.chart-area svg{width:100%;height:100%;overflow:visible}.axis{fill:#8995a5;font-size:9px}.gridline{stroke:#edf0f4;stroke-width:1}.bar{rx:4}.rankrows{display:flex;flex-direction:column;gap:14px;padding-top:7px}.rank{display:grid;grid-template-columns:110px 1fr 75px;gap:10px;align-items:center;font-size:11px}.rank-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.track{height:8px;background:#f0f3f7;border-radius:8px;overflow:hidden}.fill{height:100%;border-radius:8px;background:var(--blue)}.rank-val{text-align:right;font-weight:700}.foot{display:flex;justify-content:space-between;color:#8792a1;font-size:10px;padding:15px 3px 0}.tablecard{grid-column:span 12}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:11px}th{text-align:left;color:var(--muted);font-weight:700;border-bottom:1px solid var(--line);padding:9px 8px}td{border-bottom:1px solid #f0f2f5;padding:9px 8px}td:last-child,th:last-child{text-align:right}.pos{color:#079b8e;font-weight:700}@media(max-width:900px){.shell{padding:22px 16px}.kpi{grid-column:span 6}.wide,.narrow,.chart{grid-column:span 12}}@media(max-width:530px){.top{display:block}.tag{display:inline-block;margin-top:10px}.kpi{grid-column:span 12}.filter select{min-width:80px}.chart-area{height:205px}}
</style></head><body><div class="shell"><header class="top"><div><div class="eyebrow">Commercial intelligence</div><h1>Business performance</h1><div class="sub">Revenue, profitability and demand across markets · 2013–2014</div></div><div class="tag">FINANCIALS · LIVE FILTERS</div></header>
<section class="filters" id="filters"></section><main class="grid"><div class="card kpi"><div class="kpi-label">Net sales</div><div class="kpi-value" id="sales">—</div><div class="kpi-note">After discounts</div></div><div class="card kpi"><div class="kpi-label">Profit</div><div class="kpi-value" id="profit">—</div><div class="kpi-note" id="margin">—</div></div><div class="card kpi"><div class="kpi-label">Profit margin</div><div class="kpi-value" id="marginpct">—</div><div class="kpi-note">Profit / net sales</div></div><div class="card kpi"><div class="kpi-label">Units sold</div><div class="kpi-value" id="units">—</div><div class="kpi-note" id="transactions">—</div></div>
<div class="card chart wide"><div class="chart-head"><div><h2>Sales &amp; profit by month</h2><p>Monthly net sales with profit overlay</p></div><div class="legend">■ Sales &nbsp; ● Profit</div></div><div class="chart-area" id="trend"></div></div>
<div class="card chart narrow"><div class="chart-head"><div><h2>Sales by segment</h2><p>Share of net sales</p></div></div><div class="rankrows" id="segments"></div></div>
<div class="card chart narrow"><div class="chart-head"><div><h2>Country performance</h2><p>Ranked by net sales</p></div></div><div class="rankrows" id="countries"></div></div>
<div class="card chart wide"><div class="chart-head"><div><h2>Product mix</h2><p>Sales and contribution by product</p></div></div><div class="chart-area" id="products"></div></div>
<div class="card tablecard"><div class="chart-head"><div><h2>Top product &amp; market combinations</h2><p>Ranked by net sales</p></div></div><div class="tablewrap"><table><thead><tr><th>Product</th><th>Country</th><th>Segment</th><th>Net sales</th><th>Profit</th><th>Margin</th></tr></thead><tbody id="table"></tbody></table></div><div class="foot"><span>Source: Sample data workbook · 700 records</span><span>Discount Band has 53 blank source values; shown as “Not specified” in filters.</span></div></div></main></div>
<script>const DATA=__DATA__;
const fmt=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);const short=n=>n>=1e6?'$'+(n/1e6).toFixed(1)+'m':n>=1e3?'$'+(n/1e3).toFixed(0)+'k':fmt(n);const nf=n=>new Intl.NumberFormat('en-US').format(Math.round(n));
const defs=[['Year','Year'],['Segment','Segment'],['Country','Country'],['Product','Product']];const filters=document.getElementById('filters');defs.forEach(([key,label])=>{let d=document.createElement('div');d.className='filter';d.innerHTML='<label>'+label+'</label><select id="f_'+key.replaceAll(' ','_')+'"><option value="All">All</option>'+[...new Set(DATA.map(x=>String(x[key])))].sort().map(v=>'<option>'+v+'</option>').join('')+'</select>';filters.append(d)});let reset=document.createElement('button');reset.className='reset';reset.textContent='Reset';reset.onclick=()=>{document.querySelectorAll('select').forEach(s=>s.value='All');render()};filters.append(reset);
function selected(){return DATA.filter(x=>defs.every(([k])=>{let v=document.getElementById('f_'+k.replaceAll(' ','_')).value;return v==='All'||String(x[k])===v}))}document.querySelectorAll('select').forEach(x=>x.addEventListener('change',render));
function svgLine(rows){if(!rows.length)return '<div class="sub">No data for this selection</div>';let w=700,h=210,l=42,r=10,t=10,b=28,max=Math.max(...rows.map(x=>x.sales))*1.1;let pts=rows.map((x,i)=>[l+i*(w-l-r)/(rows.length-1||1),h-b-(x.sales/max)*(h-t-b)]);let p=pts.map(a=>a.join(',')).join(' ');let profitMax=Math.max(...rows.map(x=>x.profit))*1.1;let pp=rows.map((x,i)=>[l+i*(w-l-r)/(rows.length-1||1),h-b-(x.profit/profitMax)*(h-t-b)]).map(a=>a.join(',')).join(' ');let grid=[0,.5,1].map(q=>{let y=h-b-q*(h-t-b);return '<line class="gridline" x1="'+l+'" y1="'+y+'" x2="'+(w-r)+'" y2="'+y+'"/><text class="axis" x="2" y="'+(y+3)+'">'+short(max*q)+'</text>'}).join('');let labels=rows.map((x,i)=>'<text class="axis" text-anchor="middle" x="'+pts[i][0]+'" y="'+(h-7)+'">'+x.label+'</text>').join('');let dots=pts.map((a,i)=>'<circle cx="'+a[0]+'" cy="'+a[1]+'" r="3" fill="#2367f2"><title>'+rows[i].label+': '+fmt(rows[i].sales)+'</title></circle>').join('');return '<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">'+grid+'<polyline fill="none" stroke="#2367f2" stroke-width="3" points="'+p+'"/>'+dots+'<polyline fill="none" stroke="#10a7a0" stroke-width="2.5" stroke-dasharray="5 4" points="'+pp+'"/>'+labels+'</svg>'}
function ranking(el,items,key){let max=Math.max(...items.map(x=>x.val),1);document.getElementById(el).innerHTML=items.map((x,i)=>'<div class="rank"><div class="rank-name">'+x.name+'</div><div class="track"><div class="fill" style="width:'+100*x.val/max+'%;opacity:'+(1-i*.1)+'"></div></div><div class="rank-val">'+short(x.val)+'</div></div>').join('')||'<span class="sub">No data</span>'}
function render(){let d=selected(),sum=k=>d.reduce((a,x)=>a+(+x[k]||0),0),sales=sum('Sales'),profit=sum('Profit'),units=sum('Units Sold');document.getElementById('sales').textContent=fmt(sales);document.getElementById('profit').textContent=fmt(profit);document.getElementById('margin').innerHTML='<strong>'+((profit/sales||0)*100).toFixed(1)+'%</strong> return on net sales';document.getElementById('marginpct').textContent=((profit/sales||0)*100).toFixed(1)+'%';document.getElementById('units').textContent=nf(units);document.getElementById('transactions').textContent=nf(d.length)+' records';let month={};d.forEach(x=>{let m=x.Date.slice(0,7);month[m]??={sales:0,profit:0};month[m].sales+=+x.Sales;month[m].profit+=+x.Profit});let months=Object.entries(month).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,v])=>({label:new Date(k+'-01T00:00:00').toLocaleDateString('en-US',{month:'short',year:'2-digit'}),...v}));document.getElementById('trend').innerHTML=svgLine(months);let agg=(field)=>{let o={};d.forEach(x=>o[x[field]]=(o[x[field]]||0)+(+x.Sales||0));return Object.entries(o).map(([name,val])=>({name,val})).sort((a,b)=>b.val-a.val)};ranking('segments',agg('Segment'));ranking('countries',agg('Country'));let prods=agg('Product'),max=Math.max(...prods.map(x=>x.val),1),w=700,h=210,l=100,r=12,row=prods.length? h/prods.length:30;document.getElementById('products').innerHTML='<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">'+prods.map((x,i)=>{let y=i*row+5,bw=(w-l-r)*x.val/max;return '<text class="axis" x="0" y="'+(y+row*.6)+'">'+x.name+'</text><rect class="bar" x="'+l+'" y="'+y+'" width="'+bw+'" height="'+Math.min(20,row-7)+'" fill="'+['#2367f2','#10a7a0','#6f8ff7','#f3a33b','#7c6cf0','#e76f51'][i%6]+'"><title>'+fmt(x.val)+'</title></rect><text class="axis" x="'+(l+bw+5)+'" y="'+(y+row*.6)+'">'+short(x.val)+'</text>'}).join('')+'</svg>';let groups={};d.forEach(x=>{let k=x.Product+'|'+x.Country+'|'+x.Segment;groups[k]??={product:x.Product,country:x.Country,segment:x.Segment,sales:0,profit:0};groups[k].sales+=+x.Sales;groups[k].profit+=+x.Profit});document.getElementById('table').innerHTML=Object.values(groups).sort((a,b)=>b.sales-a.sales).slice(0,8).map(x=>'<tr><td>'+x.product+'</td><td>'+x.country+'</td><td>'+x.segment+'</td><td>'+fmt(x.sales)+'</td><td class="pos">'+fmt(x.profit)+'</td><td>'+((x.profit/x.sales)*100).toFixed(1)+'%</td></tr>').join('')}
render();</script></body></html>'''.replace('__DATA__', data)
(out / 'business-performance-dashboard.html').write_text(html, encoding='utf-8')
print(out / 'business-performance-dashboard.html')
